import java.nio.file.*;
import java.util.*;
import jdk.jfr.consumer.*;

/* java JfrShares.java <file.jfr> [name ...]: the top self frames and top inclusive
 * methods of the jdk.ExecutionSample events, and for each name given the share of the
 * samples whose stack holds a frame whose type.method contains it. */
public class JfrShares {
    public static void main(String[] a) throws Exception {
        List<RecordedEvent> evs = RecordingFile.readAllEvents(Path.of(a[0]));
        Map<String, Integer> self = new HashMap<>(), incl = new HashMap<>();
        Map<String, Integer> named = new LinkedHashMap<>();
        for (int i = 1; i < a.length; i++) named.put(a[i], 0);
        int n = 0;
        for (RecordedEvent e : evs) {
            if (!e.getEventType().getName().equals("jdk.ExecutionSample")) continue;
            RecordedStackTrace st = e.getStackTrace();
            if (st == null || st.getFrames().isEmpty()) continue;
            n++;
            List<RecordedFrame> fs = st.getFrames();
            String top = name(fs.get(0));
            self.merge(top, 1, Integer::sum);
            Set<String> seen = new HashSet<>();
            for (RecordedFrame f : fs) seen.add(name(f));
            for (String s : seen) incl.merge(s, 1, Integer::sum);
            for (String k : named.keySet())
                for (String s : seen) if (s.contains(k)) { named.merge(k, 1, Integer::sum); break; }
        }
        System.out.println("samples " + n);
        System.out.println("-- top self");
        print(self, n, 15);
        System.out.println("-- top inclusive");
        print(incl, n, 25);
        System.out.println("-- named");
        for (Map.Entry<String, Integer> k : named.entrySet())
            System.out.printf("%6d %6.2f%%  %s%n", k.getValue(), 100.0 * k.getValue() / n, k.getKey());
    }
    static String name(RecordedFrame f) {
        RecordedMethod m = f.getMethod();
        return m.getType().getName() + "." + m.getName();
    }
    static void print(Map<String, Integer> m, int n, int k) {
        m.entrySet().stream().sorted((x, y) -> y.getValue() - x.getValue()).limit(k)
         .forEach(x -> System.out.printf("%6d %6.2f%%  %s%n", x.getValue(), 100.0 * x.getValue() / n, x.getKey()));
    }
}

